#!/usr/bin/env python3
"""Generator for the q0x Rust probes. Emits the literal block and the
whole-matrix assertion blocks, so that no assertion is hand-typed and no
instantiation is hand-picked.

Reproduce: python3 gen.py   (writes the generated .rs files beside it)
"""
import sys

CORE = open("q04_core.rs").read()
# strip the crate attributes; the generated files carry their own
CORE_BODY = CORE.split("#![allow(dead_code)]", 1)[1]


def tower(n):
    if n == 0:
        return "Z"
    return ("O<" if n % 2 else "E<") + tower(n // 2) + ">"


def literals(hi):
    return "\n".join(f"pub type N{n} = {tower(n)};" for n in range(hi + 1))


def bits_for(u):
    return u.bit_length()


HEAD = """// GENERATED by gen.py. Do not hand-edit; edit the generator.
// Toolchain: rustc 1.98.0-nightly (57d06900f 2026-05-27), pin nightly-2026-05-28.
// Features: none. No -Z flags. Default solver.
#![no_std]
#![allow(dead_code)]
"""


# ---------------------------------------------------------------------------
def q05_subtraction(hi=64):
    """Whole-matrix check of Sub, SubB, Max and Min. Every pair, not a sample."""
    out = [HEAD, CORE_BODY, literals(2 * hi + 2), "\nfn _sub_matrix()\nwhere"]
    for a in range(hi + 1):
        for b in range(a + 1):
            out.append(f"    N{a}: Sub<N{b}>, Dif<N{a}, N{b}>: Same<N{a - b}>,")
    out.append("{\n}\n")
    out.append("fn _maxmin_matrix()\nwhere")
    for a in range(0, hi + 1, 3):
        for b in range(0, hi + 1, 3):
            out.append(
                f"    N{a}: Cmp<N{b}>, Ord2<N{a}, N{b}>: IfLe<N{b}, N{a}> + IfLe<N{a}, N{b}>,"
                f" Max<N{a}, N{b}>: Same<N{max(a, b)}>, Min<N{a}, N{b}>: Same<N{min(a, b)}>,"
            )
    out.append("{\n}\n")
    return "\n".join(out)


# ---------------------------------------------------------------------------
SHAPE = """
// ---- the shape algebra, in (total width, fraction width) coordinates -------
// A numeral's shape is a pair of nats (W, F). The integer width I = W - F is a
// DERIVED VIEW and is the only coordinate that ever goes negative, which is why
// it is not stored. q01 measures I < 0 at 15 of 6561 product pairs and W < 0 and
// F < 0 at zero of them.
pub struct Shape<W, F>(W, F);

// tight product (q02: exact at 6561 of 6561).
//   W = W1 + W2 - 1 when either total width is 1, else W1 + W2
//   F = F1 + F2
pub trait ProdS<R> {
    type Out;
}
pub type Prod<A, B> = <A as ProdS<B>>::Out;

impl<W1, F1, W2, F2> ProdS<Shape<W2, F2>> for Shape<W1, F1>
where
    W1: Add<W2> + Cmp<N1>,
    F1: Add<F2>,
    W2: Cmp<N1>,
    Sum<W1, W2>: Sub<N1>,
    Ord2<W2, N1>: IfEq<Dif<Sum<W1, W2>, N1>, Sum<W1, W2>>,
    Ord2<W1, N1>: IfEq<
        Dif<Sum<W1, W2>, N1>,
        <Ord2<W2, N1> as IfEq<Dif<Sum<W1, W2>, N1>, Sum<W1, W2>>>::Out,
    >,
{
    type Out = Shape<
        <Ord2<W1, N1> as IfEq<
            Dif<Sum<W1, W2>, N1>,
            <Ord2<W2, N1> as IfEq<Dif<Sum<W1, W2>, N1>, Sum<W1, W2>>>::Out,
        >>::Out,
        Sum<F1, F2>,
    >;
}

// tight sum (q03: exact at 6561 of 6561).
//   F  = max(F1, F2)
//   d_i = F - F_i          natural, since F is the max
//   A_i = W_i + d_i
//   W  = max(A1, A2) + [ min(A1, A2) > max(d1, d2) ]
pub trait SumS<R> {
    type Out;
}
pub type Plus<A, B> = <A as SumS<B>>::Out;

pub type FOut<F1, F2> = Max<F1, F2>;
pub type D<Fo, Fi> = Dif<Fo, Fi>;
pub type A_<W, Fo, Fi> = Sum<W, D<Fo, Fi>>;

impl<W1, F1, W2, F2> SumS<Shape<W2, F2>> for Shape<W1, F1>
where
    F1: Cmp<F2>,
    Ord2<F1, F2>: IfLe<F2, F1> + IfLe<F1, F2>,
    FOut<F1, F2>: Sub<F1> + Sub<F2>,
    W1: Add<D<FOut<F1, F2>, F1>>,
    W2: Add<D<FOut<F1, F2>, F2>>,
    D<FOut<F1, F2>, F1>: Cmp<D<FOut<F1, F2>, F2>>,
    Ord2<D<FOut<F1, F2>, F1>, D<FOut<F1, F2>, F2>>:
        IfLe<D<FOut<F1, F2>, F2>, D<FOut<F1, F2>, F1>>,
    A_<W1, FOut<F1, F2>, F1>: Cmp<A_<W2, FOut<F1, F2>, F2>>,
    Ord2<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>:
        IfLe<A_<W2, FOut<F1, F2>, F2>, A_<W1, FOut<F1, F2>, F1>>
            + IfLe<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>,
    Min<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>:
        Cmp<Max<D<FOut<F1, F2>, F1>, D<FOut<F1, F2>, F2>>>,
    Max<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>: AddC<Z>,
    Ord2<
        Min<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>,
        Max<D<FOut<F1, F2>, F1>, D<FOut<F1, F2>, F2>>,
    >: IfGt<
        SumC<Max<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>, Z>,
        Max<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>,
    >,
{
    type Out = Shape<
        <Ord2<
            Min<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>,
            Max<D<FOut<F1, F2>, F1>, D<FOut<F1, F2>, F2>>,
        > as IfGt<
            SumC<Max<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>, Z>,
            Max<A_<W1, FOut<F1, F2>, F1>, A_<W2, FOut<F1, F2>, F2>>,
        >>::Out,
        FOut<F1, F2>,
    >;
}
"""


def prod_wf(w1, f1, w2, f2):
    if w1 == 0 or w2 == 0:
        return None  # degenerate; the rule below does not claim this case
    w = w1 + w2 - 1 if (w1 == 1 or w2 == 1) else w1 + w2
    return (w, f1 + f2)


def add_wf(w1, f1, w2, f2):
    f = max(f1, f2)
    d1, d2 = f - f1, f - f2
    a1, a2 = w1 + d1, w2 + d2
    return (max(a1, a2) + (1 if min(a1, a2) > max(d1, d2) else 0), f)


def q06_shapes(box_n=9):
    """The shape rules, asserted over the whole (I,F) box the panel has been
    using, translated into (W,F). Degenerate W=0 operands are excluded from the
    product block and the exclusion is stated in the file."""
    shapes = [(I, F) for I in range(box_n) for F in range(box_n)]
    out = [HEAD, CORE_BODY, literals(40), SHAPE]
    out.append("fn _product_matrix()\nwhere")
    n = 0
    for (i1, f1) in shapes:
        for (i2, f2) in shapes:
            w1, w2 = i1 + f1, i2 + f2
            r = prod_wf(w1, f1, w2, f2)
            if r is None:
                continue
            out.append(
                f"    Shape<N{w1}, N{f1}>: ProdS<Shape<N{w2}, N{f2}>>,"
                f" Prod<Shape<N{w1}, N{f1}>, Shape<N{w2}, N{f2}>>:"
                f" Same<Shape<N{r[0]}, N{r[1]}>>,"
            )
            n += 1
    out.append("{\n}\n")
    out.append(f"// product assertions: {n}\n")

    out.append("fn _sum_matrix()\nwhere")
    m = 0
    for (i1, f1) in shapes:
        for (i2, f2) in shapes:
            w1, w2 = i1 + f1, i2 + f2
            r = add_wf(w1, f1, w2, f2)
            out.append(
                f"    Shape<N{w1}, N{f1}>: SumS<Shape<N{w2}, N{f2}>>,"
                f" Plus<Shape<N{w1}, N{f1}>, Shape<N{w2}, N{f2}>>:"
                f" Same<Shape<N{r[0]}, N{r[1]}>>,"
            )
            m += 1
    out.append("{\n}\n")
    out.append(f"// sum assertions: {m}\n")
    return "\n".join(out)



# ---------------------------------------------------------------------------
def q08_map(hi=200):
    """The three-input map over its whole domain here: four strategies by two
    signs by every width 0..=hi. The expected stride is the CONTAINER's width for
    Hot, Warm and Precise and the LOGICAL width for Cold, and at the wide rung
    Hot's container is padded to a multiple of 16 bytes while the others are not.
    Two earlier versions of this expectation were wrong in two different ways and
    the notes in q07_three_input_map.rs say how."""
    def rung(w):
        for b in (8, 16, 32, 64, 128):
            if w <= b:
                return b
        return None

    def up16(b):
        return ((b + 15) // 16) * 16

    lines = []
    for S in ("Hot", "Warm", "Cold", "Precise"):
        for Sn, p in (("Unsigned", "u"), ("Signed", "i")):
            for w in range(0, hi + 1):
                r = rung(w)
                by = (w + 7) // 8
                if r:
                    cont = f"{p}{r}"
                else:
                    inner = "BufOf<N%d>" % by
                    cont = f"Aligned16<{inner}>" if S == "Hot" else inner
                if S == "Cold":
                    stride = w
                elif r:
                    stride = r
                elif S == "Hot":
                    stride = 8 * up16(by)
                else:
                    stride = 8 * by
                lines.append(
                    f"    {S}: Realise<{Sn}, N{w}>,"
                    f" ContainerOf<{S}, {Sn}, N{w}>: Same<{cont}>,"
                    f" StrideBits<{S}, {Sn}, N{w}>: Same<N{stride}>,"
                )
    head = """// GENERATED by gen.py. Do not hand-edit; edit the generator.
// The three-input map asserted over its WHOLE domain in this probe: four
// strategies x two signs x every width 0..=200, which is 1608 triples, not a
// sample. A law asserted over a sample of shapes is an admission that someone
// chose what not to find out.
//
// Toolchain: rustc 1.98.0-nightly (57d06900f 2026-05-27), pin nightly-2026-05-28.
// Features: none. Edition 2024.
// Build: rustc +nightly-2026-05-28 --edition 2024 --crate-type lib \\
//          q08_map_matrix.rs --out-dir build
#![no_std]
#![allow(dead_code)]
include!("q07_body_inc.rs");

fn _map_matrix()
where
"""
    src = head + "\n".join(lines) + "\n{\n}\n" + f"// triples asserted: {len(lines)}\n"
    return src, len(lines)


def q08_controls(src):
    """Two negative controls, generated with the matrix so they can never end up
    describing a different file. One falsifies Cold's packing, the other
    falsifies Hot's wide-rung padding, which is the defect this probe found in
    itself."""
    a = ("    Cold: Realise<Unsigned, N5>, ContainerOf<Cold, Unsigned, N5>: Same<u8>,"
         " StrideBits<Cold, Unsigned, N5>: Same<N5>,")
    assert a in src, "control anchor A missing"
    ctl_a = ("// NEGATIVE CONTROL for q08, generated with it. Cold's stride at W=5\n"
             "// asserted as 8 bits, which is what a byte-padded strategy gives and\n"
             "// what Cold exists NOT to do.\n"
             + src.replace(a, a.replace("Same<N5>,", "Same<N8>,"), 1))

    b = ("    Hot: Realise<Unsigned, N200>, ContainerOf<Hot, Unsigned, N200>:"
         " Same<Aligned16<BufOf<N25>>>, StrideBits<Hot, Unsigned, N200>: Same<N256>,")
    assert b in src, "control anchor B missing"
    ctl_b = ("// SECOND NEGATIVE CONTROL, on the defect this probe found in itself.\n"
             "// Hot's wide-rung stride at W=200 asserted as 200 bits, which is\n"
             "// 8*ceil(W/8) and is what the FIRST version of the map produced. The\n"
             "// container is Aligned16<BufOf<N25>>, whose real size is 32 bytes.\n"
             + src.replace(b, b.replace("Same<N256>,", "Same<N200>,"), 1))
    return ctl_a, ctl_b


def main():
    which = sys.argv[1] if len(sys.argv) > 1 else "all"
    if which in ("all", "q05"):
        open("q05_subtraction_matrix.rs", "w").write(q05_subtraction())
        print("wrote q05_subtraction_matrix.rs")
    if which in ("all", "q06"):
        src = q06_shapes()
        open("q06_shape_matrix.rs", "w").write(src)
        print("wrote q06_shape_matrix.rs")
        # the negative control travels with the matrix, so regenerating one can
        # never leave the other describing a different file
        old = ("    Shape<N1, N1>: ProdS<Shape<N1, N1>>, "
               "Prod<Shape<N1, N1>, Shape<N1, N1>>: Same<Shape<N1, N2>>,")
        assert old in src, "negative-control anchor missing from the matrix"
        new = old.replace("Same<Shape<N1, N2>>", "Same<Shape<N2, N2>>")
        open("q06_negctl.rs", "w").write(
            "// NEGATIVE CONTROL for q06, generated alongside it. One expected\n"
            "// value falsified: the U<0,1> squared case asserted as W=2 where the\n"
            "// tight rule gives W=1. If this compiles the 6400-row matrix proves\n"
            "// nothing.\n" + src.replace(old, new, 1))
        print("wrote q06_negctl.rs")
    if which in ("all", "q08"):
        src, n = q08_map()
        open("q08_map_matrix.rs", "w").write(src)
        a, b = q08_controls(src)
        open("q08_negctl.rs", "w").write(a)
        open("q08_negctl2.rs", "w").write(b)
        print(f"wrote q08_map_matrix.rs ({n} triples), q08_negctl.rs, q08_negctl2.rs")


if __name__ == "__main__":
    main()
